import React, { memo } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { UseHeroSlider } from "../../context/HeroSliderContext";

function HeroKeyPoints({ keyPoints }) {
  const { currentSlide, animateTransition } = UseHeroSlider();

  return (
    <div className="relative w-full flex md:justify-start justify-center items-center">
      <AnimatePresence mode="wait">
        <motion.h2
          className="text-3xl lg:text-5xl font-extrabold text-center bg-gradient-to-r py-2 tracking-wide from-blue-600 via-blue-950  to-gray-700 drop-shadow-xl  bg-clip-text text-transparent"
          key={currentSlide}
          initial={{
            opacity: 0,
            x: -50, // Starts from the left
            rotateX: -30, // Slight 3D rotation
            scale: 0.8, // Smaller size
          }}
          animate={{
            opacity: 1,
            x: 0, // Moves to center
            rotateX: 0, // Removes rotation
            scale: 1, // Full size
          }}
          exit={{
            opacity: 0,
            x:50, // Moves to the right
            rotateX: 30, // Opposite 3D rotation
            scale: 0.8, // Shrinks while exiting
          }}
          transition={{
          animateTransition
          }}
        >
          {keyPoints[currentSlide]}
        </motion.h2>
      </AnimatePresence>
    </div>
  );
}

export default memo(HeroKeyPoints);
