import React, { createContext, useContext, useEffect, useState } from 'react'

const HeroSliderContext=createContext(null)
const animateTransition={
  duration: 2,}
export default function HeroSliderProvider({length,children,delay}) {
    const [currentSlide,setCurrentSlide]=useState(0)
    useEffect(() => {
        const interval = setInterval(() => {
          setCurrentSlide((prevIndex) =>
            prevIndex === length - 1 ? 0 : prevIndex + 1
          );
        }, delay); // Change image every 3 seconds
        return () => clearInterval(interval);
      }, []);
  return (
    <HeroSliderContext.Provider value={{currentSlide,setCurrentSlide,animateTransition}}>
{children}
    </HeroSliderContext.Provider>
  )
}

export const UseHeroSlider=()=>useContext(HeroSliderContext)